CREATE TABLE payments(id BINARY(16) PRIMARY KEY,tenant_id BINARY(16) NOT NULL,user_id BINARY(16) NOT NULL,bill_id BINARY(16) NOT NULL,invoice_id BINARY(16),idempotency_key VARCHAR(64) NOT NULL UNIQUE,provider VARCHAR(50) NOT NULL,payment_method VARCHAR(30) NOT NULL,amount DECIMAL(12,2) NOT NULL,currency VARCHAR(3) NOT NULL,status VARCHAR(20) NOT NULL,provider_reference VARCHAR(150),failure_reason VARCHAR(500),created_at TIMESTAMP(6) NOT NULL,completed_at TIMESTAMP(6),refunded_at TIMESTAMP(6),updated_at TIMESTAMP(6) NOT NULL);CREATE INDEX idx_payments_tenant_created ON payments(tenant_id,created_at);CREATE INDEX idx_payments_bill ON payments(bill_id);CREATE INDEX idx_payments_invoice ON payments(invoice_id);
